using Dev2.Common;
using Newtonsoft.Json;
using System;
using System.Collections.Frozen;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace Warewolf.Execution.Lightweight.Mcp;

/// <summary>
/// Reads <c>Resources/fidelity-allowlist.json</c> — the per-activity-type round-trip
/// fidelity results generated by <c>RoundTripFidelityTests</c>
/// (<c>Warewolf.Execution.Lightweight.Integration.Tests/Coverage/</c>) — and answers the single
/// question <c>get_workflow_definition</c>/<c>list_workflows</c> need per spec's
/// "<c>bodyEditable</c> gating" section: does this <c>StudioName</c> pass the round-trip
/// fidelity gate.
///
/// <para>
/// <b>Only <c>Status == "Pass"</c> counts.</b> <c>PassBothFailedIdentically</c> only proves
/// original and round-tripped XAML failed identically on a no-input smoke execution
/// (typically before the activity under test even runs, e.g. a missing required variable) —
/// it does not prove the activity's own logic round-trips. Treating it as sufficient would
/// risk silently exposing a body an LLM caller could not actually reconstruct faithfully.
/// <c>NoCorpusSample</c> and <c>TranslationFailed</c> are conservatively non-editable for the
/// same "prove it, don't assume it" reason the spec states for the whole gate.
/// </para>
///
/// <para>
/// <b>Fails closed by design.</b> <c>Resources\**\*</c> in
/// <c>Warewolf.Execution.Lightweight.csproj</c> only copies to the output directory in Debug
/// builds (Release deployments are expected to supply their own resources) — so this file may
/// legitimately be absent. When it is, every lookup returns <c>false</c>, matching the spec's
/// own conservative default ("a workflow using even one non-allow-listed ... activity type
/// stays <c>bodyEditable: false</c>") rather than throwing or crashing the tool call.
/// </para>
/// </summary>
internal static class FidelityAllowList
{
    internal const string PassStatus = "Pass";

    static readonly Lazy<FrozenDictionary<string, string>> _statusByStudioName =
        new(LoadFromDefaultLocation, System.Threading.LazyThreadSafetyMode.ExecutionAndPublication);

    /// <summary>
    /// Returns whether <paramref name="studioName"/> (a <see cref="ToolCatalog.Entry.Name"/>)
    /// has passed round-trip fidelity testing, i.e. is safe to report as contributing to a
    /// <c>bodyEditable: true</c> workflow. Case-insensitive; unknown names return <c>false</c>.
    /// </summary>
    internal static bool IsEditable(string studioName)
    {
        if (string.IsNullOrWhiteSpace(studioName))
        {
            return false;
        }

        return _statusByStudioName.Value.TryGetValue(studioName, out var status)
            && string.Equals(status, PassStatus, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>Returns the raw <c>Status</c> value for <paramref name="studioName"/>, or <c>null</c> when absent.</summary>
    internal static string? StatusFor(string studioName) =>
        !string.IsNullOrWhiteSpace(studioName) && _statusByStudioName.Value.TryGetValue(studioName, out var status)
            ? status
            : null;

    static FrozenDictionary<string, string> LoadFromDefaultLocation()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Resources", "fidelity-allowlist.json");
        return LoadFromFile(path);
    }

    /// <summary>
    /// Loads and parses <paramref name="path"/>. Internal (not <c>private</c>) so tests can
    /// point at a fixture file without depending on <see cref="AppContext.BaseDirectory"/>.
    /// Returns an empty map — never throws — when the file is missing or malformed.
    /// </summary>
    internal static FrozenDictionary<string, string> LoadFromFile(string path)
    {
        try
        {
            if (!File.Exists(path))
            {
                Dev2Logger.Warn($"FidelityAllowList file not found at: {path}. All workflows will report bodyEditable:false.", "FidelityAllowList");
                return FrozenDictionary<string, string>.Empty;
            }

            var json = File.ReadAllText(path);
            var document = JsonConvert.DeserializeObject<AllowListDocument>(json);
            var results = document?.Results;
            if (results is null or { Count: 0 })
            {
                Dev2Logger.Warn($"FidelityAllowList at '{path}' parsed with no results.", "FidelityAllowList");
                return FrozenDictionary<string, string>.Empty;
            }

            return results
                .Where(r => !string.IsNullOrWhiteSpace(r.StudioName) && !string.IsNullOrWhiteSpace(r.Status))
                .ToFrozenDictionary(r => r.StudioName!, r => r.Status!, StringComparer.OrdinalIgnoreCase);
        }
        catch (Exception ex)
        {
            Dev2Logger.Error($"FidelityAllowList failed to load from: {path}", ex, "FidelityAllowList");
            return FrozenDictionary<string, string>.Empty;
        }
    }

    sealed class AllowListDocument
    {
        [JsonProperty("results")]
        public List<AllowListEntry>? Results { get; set; }
    }

    sealed class AllowListEntry
    {
        [JsonProperty("StudioName")]
        public string? StudioName { get; set; }

        [JsonProperty("Status")]
        public string? Status { get; set; }
    }
}
